<script>
(() => {
  const graph = document.getElementById('graph'), svg = document.getElementById('graphSvg');
  const sheet = document.getElementById('sheet'), keyboard = document.getElementById('keyboard');
  const entry = document.getElementById('entry'), toolsPanel = document.getElementById('toolsPanel');
  const tablePanel = document.getElementById('tablePanel'), spreadPanel = document.getElementById('spreadPanel');
  const warning = document.getElementById('warning'), moreButton = document.getElementById('moreButton');
  const keyGrid = document.getElementById('keyGrid');
  let mode='algebra', keyboardMode='numeric', expr='', invalid=false;
  let graphCollapsed=false;

  function buildGraph() {
    const w=innerWidth, h=graph.clientHeight;
    svg.setAttribute('viewBox',`0 0 ${w} ${h}`);
    const expanded=graph.classList.contains('expanded');
    const oy=expanded ? h*.70 : h*.5;
    const ox=w/2, unit=w/8;
    let out='';
    out += `<line class="axis" x1="0" y1="${oy}" x2="${w-2}" y2="${oy}"/><path d="M ${w-7} ${oy-5} L ${w-1} ${oy} L ${w-7} ${oy+5}" fill="none" stroke="#555" stroke-width="1.4"/>`;
    out += `<line class="axis" x1="${ox}" y1="${h}" x2="${ox}" y2="2"/><path d="M ${ox-5} 8 L ${ox} 1 L ${ox+5} 8" fill="none" stroke="#555" stroke-width="1.4"/>`;
    for(let n=-4;n<=4;n++){
      let x=ox+n*unit;
      out+=`<text class="tick-label" x="${x}" y="${oy+24}" text-anchor="middle">${n}</text>`;
    }
    let top=Math.ceil((oy-h)/unit), bot=Math.floor(oy/unit);
    for(let n=top;n<=bot;n++){
      if(n===0) continue;
      let y=oy-n*unit;
      out+=`<text class="tick-label" x="${ox-11}" y="${y+6}" text-anchor="end">${n}</text>`;
    }
    if(expr && (expr==='sin(x)' || expr==='sin(xln(x))' || expr==='sin(xln())')) {
      let d='', first=true;
      for(let px=0;px<=w;px+=2){
        let x=(px-ox)/unit, y;
        if(expr==='sin(x)') y=Math.sin(x);
        else if(x<=0) continue;
        else y=Math.sin(x*Math.log(x));
        const py=oy-y*unit;
        d+=(first?'M':'L')+px.toFixed(1)+' '+py.toFixed(1)+' '; first=false;
      }
      out+=`<path class="plot" d="${d}"/>`;
      let points=expr==='sin(x)'?[-Math.PI, -Math.PI/2,0,Math.PI/2,Math.PI]:[.36,1,2.1,3,3.65];
      points.forEach(x=>{
        if(expr!=='sin(x)' && x<=0) return;
        let y=expr==='sin(x)'?Math.sin(x):Math.sin(x*Math.log(x));
        out+=`<circle class="plot-dot" cx="${ox+x*unit}" cy="${oy-y*unit}" r="7.2"/>`;
      });
    }
    svg.innerHTML=out;
  }
  function setTab(tab){
    mode=tab;
    document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));
    toolsPanel.style.display=tab==='tools'?'block':'none';
    tablePanel.style.display=tab==='table'?'table':'none';
    spreadPanel.style.display=tab==='spreadsheet'?'block':'none';
    const algebra=tab==='algebra';
    document.getElementById('inputRow').style.display=algebra?'flex':'none';
    document.querySelector('.brand-note').style.display=algebra?'block':'none';
    sheet.style.top='';
    graph.classList.toggle('expanded', graphCollapsed);
    buildGraph();
  }
  function updateEntry(){
    entry.classList.toggle('placeholder',!expr);
    entry.innerHTML=expr ? escapeHtml(expr)+(keyboard.classList.contains('show')?'<span class="cursor"></span>':'') : 'Input...';
    warning.style.display=invalid?'flex':'none';
    document.getElementById('plusButton').style.display=invalid?'none':'flex';
    moreButton.style.display=expr?'block':'none';
    buildGraph();
  }
  function escapeHtml(s){ return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;'); }
  function showKeyboard(){
    setTab('algebra');
    keyboard.classList.add('show');
    graph.classList.add('keyboard-open');
    graph.classList.remove('expanded');
    graphCollapsed=false;
    updateEntry();
  }
  function hideKeyboard(){
    keyboard.classList.remove('show');
    graph.classList.remove('keyboard-open');
    updateEntry();
  }
  function evaluate(){
    if(expr==='sin()' || expr==='sin(xln())'){ invalid=true; }
    else { invalid=false; }
    if(expr==='sin(x)') graphCollapsed=false;
    hideKeyboard();
  }

  const numeric = ['x','y','π','e','7','8','9','×','÷','□²','□','√□','▥','4','5','6','+','−','<','>','▤','⁙','1','2','3','=','⌫','ans',',','(',')','0','.','‹','›','↵'];
  const functions = ['sin','cos','tan','%','!','$','°','sin⁻¹','cos⁻¹','tan⁻¹','{','}','≤','≥','ln','log₁₀','log⋅','d/dx','∫','i','⌫','e□','10□','√□','▤','‹','›','↵'];
  const letters = ['q','w','e','r','t','y','u','i','o','p','a','s','d','f','g','h','j','k','l','⌃','z','x','c','v','b','n','m','⌫','αβγ',',','(',')','','‹','›','↵'];
  function drawKeys(){
    keyGrid.innerHTML='';
    keyGrid.className='key-grid '+keyboardMode;
    let data=keyboardMode==='functions'?functions:keyboardMode==='letters'?letters:numeric;
    data.forEach((label,index)=>{
      const b=document.createElement('button'); b.className='key btn';
      if(['⌫','↵','‹','›','⌃','αβγ'].includes(label)) b.classList.add('dark');
      if(label==='') b.classList.add('wide');
      if(['□²','√□','▥','▤','⁙','e□','10□','log⋅','d/dx'].includes(label)) b.classList.add('small');
      b.textContent=label;
      b.addEventListener('click',()=>pressKey(label));
      keyGrid.appendChild(b);
    });
  }
  function pressKey(k){
    if(k==='⌫'){ expr=expr.slice(0,-1); invalid=false; updateEntry(); return; }
    if(k==='↵'){ evaluate(); return; }
    if(k==='‹'||k==='›'||k==='⌃'||k==='αβγ'||k===''){return;}
    if(k==='sin'||k==='cos'||k==='tan'||k==='ln') {
      expr += k+'()'; invalid=true;
    } else if(k==='x' && expr==='sin()'){
      expr='sin(x)'; invalid=false;
    } else if(k==='x' && expr==='sin(xln())'){
      expr='sin(xln(x))'; invalid=false;
    } else if(k==='x' && expr.endsWith('ln()')){
      expr=expr.slice(0,-1)+'x)';
      invalid=false;
    } else {
      expr += k==='×'?'*':k==='÷'?'/':k;
      invalid=false;
    }
    updateEntry();
  }
  document.querySelectorAll('[data-keymode]').forEach(b=>b.addEventListener('click',()=>{
    keyboardMode=b.dataset.keymode==='symbols'?'numeric':b.dataset.keymode;
    document.querySelectorAll('.key-tab').forEach(t=>t.classList.toggle('active',t===b));
    drawKeys();
  }));
  document.getElementById('closeKeyboard').addEventListener('click',hideKeyboard);
  entry.addEventListener('click',()=>{ if(!expr) expr=''; showKeyboard(); });
  entry.addEventListener('keydown',e=>{if(e.key==='Enter')showKeyboard();});
  document.getElementById('plusButton').addEventListener('click',()=>{expr='';invalid=false;showKeyboard();});
  document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{hideKeyboard();setTab(b.dataset.tab);}));
  document.getElementById('menuButton').addEventListener('click',()=>document.getElementById('menuPop').classList.toggle('show'));
  document.querySelector('.gear').addEventListener('click',()=>{});
  document.querySelectorAll('.tool').forEach(b=>b.addEventListener('click',()=>{
    document.querySelectorAll('.tool').forEach(t=>t.classList.remove('selected'));b.classList.add('selected');
  }));
  moreButton.addEventListener('click',()=>{});
  function fillTables(){
    tablePanel.innerHTML='<tbody><tr class="thead"><td></td><td>A</td><td>B</td><td>C</td></tr>'+[1,2,3,4,5,6].map(n=>`<tr><td class="rowhead">${n}</td><td></td><td></td><td></td></tr>`).join('')+'</tbody>';
    const sg=document.getElementById('spreadGrid');
    sg.innerHTML='<div class="spread-cell heading"></div>'+['A','B','C'].map(x=>`<div class="spread-cell heading">${x}</div>`).join('')+
    Array.from({length:7},(_,i)=>`<div class="spread-cell heading">${i+1}</div><div class="spread-cell"></div><div class="spread-cell"></div><div class="spread-cell"></div>`).join('');
  }
  fillTables();drawKeys();buildGraph();
  window.addEventListener('resize',buildGraph);
  let startY=0;
  document.querySelector('.handle').addEventListener('touchstart',e=>startY=e.touches[0].clientY,{passive:true});
  document.querySelector('.handle').addEventListener('touchend',e=>{
    const delta=e.changedTouches[0].clientY-startY;
    if(delta>70){graphCollapsed=true;graph.classList.add('expanded');sheet.style.top='calc(100dvh - 421px)';buildGraph();}
    if(delta<-70){graphCollapsed=false;graph.classList.remove('expanded');buildGraph();}
  });
})();
</script>
